item_ext_desc[91565] = "\r^d7c4a2“西部牛仔”一群洋溢著熱情無畏的先驅者，在那曾經馳騁的熱土上留下的痕跡與神秘七寶城的寶藏如今已成傳說。"
item_ext_desc[91566] = "\r^d7c4a2“西部牛仔”一群洋溢著熱情無畏的先驅者，在那曾經馳騁的熱土上留下的痕跡與神秘七寶城的寶藏如今已成傳說。"
item_ext_desc[91602] = "\r^d7c4a2聖紅蝎喜歡的食物"
item_ext_desc[91603] = "\r^d7c4a2線香一柱，祈君平安"
item_ext_desc[91681] = "\r^d7c4a2夜嵐谷可不常存有這種香燭，每一根都很珍貴。"
item_ext_desc[91683] = "\r^d7c4a2材質不錯的布匹，各大游商處都有售。"
item_ext_desc[91685] = "\r^d7c4a2據說能索人性命於無形的神秘藥劑。"
item_ext_desc[91686] = "\r^d7c4a2藥王馮給你的一把消過毒後的小刀。"
item_ext_desc[91687] = "\r^d7c4a2裝啥都能用的酒壇。只要大小合適。"
item_ext_desc[91689] = "\r^d7c4a2施肥用的，味很重。。"
item_ext_desc[91703] = "\r^d7c4a2時時勤擦拭，勿使惹塵埃"
item_ext_desc[91788] = "\r^d7c4a2青城派的人，林平之一個也不打算放過。"
item_ext_desc[91790] = "\r^d7c4a2可以記錄神器屬性的神奇的令牌。"
item_ext_desc[91795] = "\r^d7c4a2白蓮教的秘密通信，也許上面會有被綁村民的信息。"
item_ext_desc[91796] = "\r^d7c4a2被嵩山派搶去的救命藥引。"
item_ext_desc[91797] = "\r^d7c4a2秋葉蝶的翅膀。"
item_ext_desc[91798] = "\r^d7c4a2紅狸的尾巴。"
item_ext_desc[91799] = "\r^d7c4a2夜蝠的爪子。"
item_ext_desc[91800] = "\r^d7c4a2木人身上的神奇產物。"
item_ext_desc[91801] = "\r^d7c4a2將可憐的村民解救出來"
item_ext_desc[91803] = "\r^d7c4a2絕世寶劍，需經千錘百煉---眉間寸"
item_ext_desc[91810] = "\r^d7c4a2清香一柱，祈君平安"
item_ext_desc[91811] = "\r^d7c4a2水自清流，佛在心頭"
item_ext_desc[91813] = "\r^d7c4a2峨嵋派療傷聖藥，內門弟子才能擁有。"
item_ext_desc[91814] = "\r^d7c4a2待洗煉的材料。"
item_ext_desc[91815] = "\r^d7c4a2用於維修機關人。"
item_ext_desc[91816] = "\r^d7c4a2日月神教特產，誰用誰知道。"
item_ext_desc[91817] = "\r^d7c4a2很可疑的傷藥。"
item_ext_desc[91818] = "\r^d7c4a2非常乾淨，用來擦洗昭君墓。"
item_ext_desc[91819] = "\r^d7c4a2看起來很普通。"
item_ext_desc[91820] = "\r^d7c4a2油光水滑，一看就可以賣出好價錢！"
